158	    public String getRedirectUrl(@NonNull Token token, @NonNull String restOfPath) {
159	        String resourceRootUrl = getResourceRootUrl();
160	        if (!restOfPath.startsWith("/")) {
161	            // Unsure whether this can happen -- just be safe here
162	            restOfPath = "/" + restOfPath;
163	        }
164	        return resourceRootUrl + getUrlName() + "/" + token.encode() + Arrays.stream(restOfPath.split("[/]")).map(Util::rawEncode).collect(Collectors.joining("/"));
165	    }
