277	    public static class Token {
278	        private String path;
279	        private String username;
280	        private Instant timestamp;
281	
282	        @VisibleForTesting
283	        Token(@NonNull String path, @Nullable String username, @NonNull Instant timestamp) {
284	            this.path = path;
285	            this.username = Util.fixNull(username);
286	            this.timestamp = timestamp;
287	        }
288	
289	        private String encode() {
290	            String value = timestamp.toEpochMilli() + ":" + username.length() + ":" + username + ":" + path;
291	            byte[] valueBytes = value.getBytes(StandardCharsets.UTF_8);
292	            byte[] macBytes = KEY.mac(valueBytes);
293	            byte[] result = new byte[macBytes.length + valueBytes.length];
294	            System.arraycopy(macBytes, 0, result, 0, macBytes.length);
295	            System.arraycopy(valueBytes, 0, result, macBytes.length, valueBytes.length);
296	            return Base64.getUrlEncoder().encodeToString(result);
297	        }
298	
299	        private static Token decode(String value) {
300	            try {
301	                byte[] byteValue = Base64.getUrlDecoder().decode(value);
302	                byte[] mac = Arrays.copyOf(byteValue, 32);
303	                byte[] restBytes = Arrays.copyOfRange(byteValue, 32, byteValue.length);
304	                String rest = new String(restBytes, StandardCharsets.UTF_8);
305	                if (!KEY.checkMac(restBytes, mac)) {
306	                    throw new IllegalArgumentException("Failed mac check for " + rest);
307	                }
308	
309	                String[] splits = rest.split("[:]", 3);
310	                String epoch = splits[0];
311	                int authenticationNameLength = Integer.parseInt(splits[1]);
312	                String authenticationNameAndBrowserUrl = splits[2];
313	                String authenticationName = authenticationNameAndBrowserUrl.substring(0, authenticationNameLength);
314	                String browserUrl = authenticationNameAndBrowserUrl.substring(authenticationNameLength + 1);
315	                return new Token(browserUrl, authenticationName, ofEpochMilli(Long.parseLong(epoch)));
316	            } catch (RuntimeException ex) {
317	                // Choose log level that hides people messing with the URLs
318	                LOGGER.log(Level.FINE, "Failure decoding", ex);
319	                return null;
320	            }
321	        }
322	
323	    }
324	
325	    private static HMACConfidentialKey KEY = new HMACConfidentialKey(ResourceDomainRootAction.class, "key");
